import AppKit

struct DynamicsSettings:Codable,Equatable {
    var source=0,compressor=true,sidechain=true,threshold = -24,ratio=3,attack=5,release=150,makeup=0,duckThreshold = -30,depth=6
    static var disabled:DynamicsSettings{var d=DynamicsSettings();d.compressor=false;d.sidechain=false;return d}
    var valid:Bool{(0...23).contains(source)&&(-60...0).contains(threshold)&&(1...20).contains(ratio)&&(1...100).contains(attack)&&(20...1000).contains(release)&&(-12...12).contains(makeup)&&(-60...0).contains(duckThreshold)&&(0...18).contains(depth)}
    func publish(){tm_dynamics(Int32(source),compressor ? 1:0,sidechain ? 1:0,Int32(threshold),Int32(ratio),Int32(attack),Int32(release),Int32(makeup),Int32(duckThreshold),Int32(depth))}
}

extension Tracker {
    var dynamicsSettings:DynamicsSettings{project.dynamics ?? .disabled}
    func openDynamics(){fxFocus=16;dynamicsFocus=0;needsDisplay=true}
    func updateDynamics(_ d:DynamicsSettings){guard d.valid else{return};checkpoint();project.dynamics=d;d.publish();needsDisplay=true}
    func dynamicsRows()->[(String,String)]{let d=dynamicsSettings;return [("Source track","T\(String(format:"%02d",d.source+1))"),("Compressor",d.compressor ? "ON":"OFF"),("Threshold","\(d.threshold) dB"),("Ratio","\(d.ratio):1"),("Makeup gain","\(d.makeup) dB"),("Master sidechain",d.sidechain ? "ON":"OFF"),("Duck threshold","\(d.duckThreshold) dB"),("Max reduction","\(d.depth) dB"),("Attack (both)","\(d.attack) ms"),("Release (both)","\(d.release) ms")]}
    func changeDynamics(_ delta:Int){var d=dynamicsSettings;switch dynamicsFocus{case 0:d.source=max(0,min(23,d.source+delta));case 1:d.compressor.toggle();case 2:d.threshold=max(-60,min(0,d.threshold+delta));case 3:d.ratio=max(1,min(20,d.ratio+delta));case 4:d.makeup=max(-12,min(12,d.makeup+delta));case 5:d.sidechain.toggle();case 6:d.duckThreshold=max(-60,min(0,d.duckThreshold+delta));case 7:d.depth=max(0,min(18,d.depth+delta));case 8:d.attack=max(1,min(100,d.attack+delta));case 9:d.release=max(20,min(1000,d.release+delta*10));default:break};updateDynamics(d)}
    func dynamicsKey(_ event:NSEvent)->Bool{let k=event.keyCode,c=event.charactersIgnoringModifiers?.lowercased() ?? "",d=event.modifierFlags.contains(.shift) ? 5:1;if c=="a"{fxFocus=12;return true};if c=="c"{fxFocus=0;return true};switch k{case 53:selectPage(3);case 126:dynamicsFocus=max(0,dynamicsFocus-1);case 125:dynamicsFocus=min(9,dynamicsFocus+1);case 123:dynamicsFocus=max(0,dynamicsFocus-5);case 124:dynamicsFocus=min(9,dynamicsFocus+5);case 36,76:if dynamicsFocus==1||dynamicsFocus==5{changeDynamics(1)};default:if c=="q"{changeDynamics(-d)}else if c=="e"{changeDynamics(d)}else{return false}};needsDisplay=true;return true}
    func drawDynamics(){let w=bounds.width,col=(w-130)/2,rh=min(58,max(28,(footerY-235)/5));txt("FX SETTINGS / COMPRESSOR & SIDECHAIN",55,65,12,teal,true);txt("Selected track is compressed and provides the sidechain key. Its dry signal is excluded from master ducking.",55,95,12,gray(0.8));txt("SOURCE COMPRESSOR",55,128,12,purple,true);txt("MASTER SIDECHAIN",65+col,128,12,purple,true);let rows=dynamicsRows();for i in rows.indices{let x=i<5 ? 55:65+col,y=150+CGFloat(i%5)*rh;rect(x,y,col-15,rh-4,i==dynamicsFocus ? gray(0.32):gray(0.19));if i==dynamicsFocus{border(x,y,col-15,rh-4,teal)};txt(rows[i].0,x+12,y+8,12,gray(0.85),true);txt(rows[i].1,x+col*0.55,y+8,12,i==dynamicsFocus ? teal:yellow,true)};let y=150+5*rh+20;for i in 0..<2{let x=i==0 ? 55:65+col,gr=Double(tm_dynamics_gain_reduction(Int32(i)));txt(String(format:"GAIN REDUCTION  %.1f dB",gr),x,y,12,teal,true);rect(x,y+25,col-30,10,gray(0.3));rect(x,y+25,(col-30)*CGFloat(min(1,gr/18)),10,purple)};txt("↑ ↓ parameter   ← → section   Q/E value   Shift fast   F5 Reset   F7 EQ   Esc Mixer",55,footerY-25,12,gray(0.7))}
    func dynamicsMouse(_ p:NSPoint)->Bool{let col=(bounds.width-130)/2,rh=min(58,max(28,(footerY-235)/5));guard p.y>=150&&p.y<150+5*rh else{return false};dynamicsFocus=Int((p.y-150)/rh)+(p.x>=65+col ? 5:0);needsDisplay=true;return true}
}

func dynamicsSelfTest(){let t=Tracker(frame:NSRect(x:0,y:0,width:1440,height:900));precondition(t.dynamicsSettings.source==0&&t.dynamicsSettings.compressor&&t.dynamicsSettings.sidechain);t.selectPage(11);t.soft(5,shift:false);precondition(t.fxFocus==16);t.changeDynamics(3);precondition(t.dynamicsSettings.source==3);t.dynamicsFocus=7;t.changeDynamics(2);precondition(t.dynamicsSettings.depth==8);let p=try! JSONDecoder().decode(Project.self,from:JSONEncoder().encode(t.project));precondition(t.valid(p)&&p.dynamics==t.dynamicsSettings);print("Compressor and sidechain routing/settings roundtrip passed")}
